problem_statement:
You are given an old-style JavaScript utility that processes employee data. Modernize it using suitable ES6+ features while preserving its behavior.

Legacy implementation:

var employees = [
  { name: "Asha", department: "Engineering", active: true, salary: 45000 },
  { name: "Ravi", department: "Support", active: false, salary: 32000 },
  { name: "Meera", department: "Engineering", active: true, salary: 52000 }
];

var getActiveEmployees = function(list) {
  var activeEmployees = [];
  for (var i = 0; i < list.length; i++) {
    if (list[i].active === true) {
      activeEmployees.push(list[i]);
    }
  }
  return activeEmployees;
};

var createEmployeeLabels = function(list) {
  var labels = [];
  for (var i = 0; i < list.length; i++) {
    labels.push(list[i].name + " (" + list[i].department + ")");
  }
  return labels;
};

var activeEmployees = getActiveEmployees(employees);
var labels = createEmployeeLabels(activeEmployees);

console.log("Active employees: " + activeEmployees.length);
console.log(labels);

Refactor this utility using ES6+ idioms. Keep the same data and results: select only employees whose active property is true, create labels in the format Name (Department), and display the active employee count and labels. Preserve the original order and do not add unrelated features.
